import { useId } from 'react';
import './ListWorkspace.css';
export interface Item { id: string; title: string }
export interface ListState { items: readonly Item[] | null; pending: boolean; error: string | null }
export function ListWorkspace({ state, onRetry, onCreate, onOpen }: { state: ListState; onRetry: () => void; onCreate: () => void; onOpen: (id: string) => void }) {
  const id = useId();
  const initial = state.items === null;
  return <section className="list-workspace" aria-labelledby={id}><header><h1 id={id}>Projects</h1><button type="button" onClick={onCreate}>New project</button></header>
    <p className="list-status" role="status">{state.pending ? initial ? 'Loading projects…' : 'Refreshing projects. Showing saved results.' : ''}</p>
    {state.error && <div className="list-error" role="alert"><strong>Could not {initial ? 'load' : 'refresh'} projects.</strong><p>{state.error}</p>{!initial && <p>Previously loaded results are still shown.</p>}<button type="button" disabled={state.pending} onClick={onRetry}>Try again</button></div>}
    <div aria-busy={state.pending}>
      {initial ? !state.pending && !state.error ? <p>Projects have not loaded yet. <button onClick={onRetry}>Load projects</button></p> : null : state.items.length === 0 ? <div className="list-empty"><h2>No projects yet</h2><p>Create a project to get started.</p></div> : <ul>{state.items.map(item => <li key={item.id}><button type="button" onClick={() => onOpen(item.id)}>{item.title}</button></li>)}</ul>}
    </div>
  </section>;
}

