.list-workspace { max-width: 60rem; padding: 1rem; color: #20232a; }
.list-workspace header { display: flex; align-items: center; justify-content: space-between; gap: 1rem; flex-wrap: wrap; }
.list-workspace button { font: inherit; padding: .5rem .75rem; }
.list-workspace button:focus-visible { outline: 3px solid #205ed8; outline-offset: 2px; }
.list-status { min-height: 1.5em; }
.list-error { border: 2px solid #963627; padding: 1rem; margin-bottom: 1rem; border-radius: .4rem; }
.list-empty { border: 1px dashed #a0a6b0; padding: 2rem; }
.list-workspace ul { padding: 0; list-style: none; }
.list-workspace li { padding-block: .5rem; border-bottom: 1px solid #c5c9d0; overflow-wrap: anywhere; }
